class Order {
  constructor(id, effort) {
    this.id = id;
    this.effort = effort;
  }
}

class Worker {
  constructor(name, energy) {
    this.name = name;
    this.energy = energy;
    this.itemsCompleted = 0;
  }

  completeOrder(order) {
    this.energy = Math.max(0, this.energy - order.effort);
    this.itemsCompleted += 1;
  }

  isExhausted() {
    return this.energy <= 0;
  }
}

const worker = new Worker("Rin", 10);
worker.completeOrder(new Order(1, 4));
console.log(worker.energy);
console.log(worker.itemsCompleted);
console.log(worker.isExhausted());

